pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: amount to send and a boolean that decides whether attacker uses reentrancy.
    // The fuzzer will try to find a case where the mutant breaks the invariant but reference holds.
    function testFuzz_property(uint256 sendAmt, bool useReentrant) public {
        // keep sendAmt in a reasonable range and non-zero to be meaningful
        sendAmt = bound(sendAmt, 1 wei, 10 ether);

        // Deploy attacker helper that will try to reenter C during its receive/fallback
        Attacker attacker = new Attacker(address(c));

        // Fund attacker and the externally-owned test actor
        vm.deal(address(attacker), sendAmt * 2);
        vm.deal(address(this), sendAmt * 2);

        // Choose which actor will call Put: either the attacker contract (to attempt reentrancy) or this test EOA
        address payer = useReentrant ? address(attacker) : address(this);

        // Record previous recorded balance for payer
        uint256 prevRecorded;
        if (payer == address(this)) {
            prevRecorded = c.Acc(address(this)).balance; // using public getter struct requires .balance
        } else {
            prevRecorded = c.Acc(address(attacker)).balance;
        }

        // The attacker is configured to attempt reentrancy only if useReentrant is true
        attacker.setAttemptReentry(useReentrant);

        // Perform the payable Put call from chosen payer
        if (payer == address(this)) {
            // this test contract calls Put
            // ensure this contract has funds
            vm.prank(address(this));
            // send sendAmt to Put with unlockTime 0
            c.Put{value: sendAmt}(0);
        } else {
            // attacker will call Put and may reenter
            attacker.callPut{value: sendAmt}(0);
        }

        // After Put completes, the invariant: Acc[payer].balance == prevRecorded + sendAmt should hold in reference
        // For mutant it can be violated when reentrancy occurs during Put.
        uint256 afterRecorded;
        if (payer == address(this)) {
            afterRecorded = c.Acc(address(this)).balance;
        } else {
            afterRecorded = c.Acc(address(attacker)).balance;
        }

        // Single assertion: reference satisfies this for all inputs; mutant will fail for some.
        assertTrue(afterRecorded == prevRecorded + sendAmt);
    }
}

// Minimal attacker that attempts reentrant call during its fallback when configured
contract Attacker {
    C public target;
    bool public attemptReentry;

    constructor(address _t) payable {
        target = C(_t);
        attemptReentry = false;
    }

    function setAttemptReentry(bool v) external {
        attemptReentry = v;
    }

    // Caller to initiate Put from attacker
    function callPut(uint _unlockTime) external payable {
        // forward ether to target Put
        target.Put{value: msg.value}(_unlockTime);
    }

    // receive/fallback will try to reenter target. This models a reentrant caller during Put's execution
    receive() external payable {
        if (attemptReentry) {
            // try to call Put again with zero value to attempt to disturb state in mutant
            // call with small gas and zero value; if it reenters and mutant lacks guard, it may affect state
            // use low-level call to avoid reverting the original flow on failure
            (bool ok, ) = address(target).call{value: 0}(abi.encodeWithSignature("Put(uint256)", 0));
            ok; // ignore result
        }
    }
}

