pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // We'll track how much a given attacker address has sent to C via Put (including reentrant behavior),
    // and assert that Acc[attacker].balance >= totalSent for the reference. The mutant that removes the
    // reentrancy guard can reenter and withdraw during Put causing Acc balance to be smaller than
    // totalSent for some fuzzed inputs.

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: amount to send in initial Put, and a bool indicating whether the attacker will attempt reentrancy
    // We use an attacker contract to perform reentrancy when it receives ether.
    function testFuzz_property(uint256 sendAmount, bool doReenter) public {
        // keep amounts in a reasonable range and non-zero
        sendAmount = bound(sendAmount, 1 wei, 10 ether);

        // deploy attacker and fund it
        Attacker attacker = new Attacker(address(c));
        address atk = address(attacker);
        vm.deal(atk, sendAmount + 1 ether);

        // configure attacker: whether to reenter and how much to withdraw when reentering
        // choose withdraw amount as portion of sendAmount to let fuzzer explore different behaviors
        uint256 withdrawAmount = sendAmount / 2;
        attacker.configure(doReenter, withdrawAmount);

        // record prior recorded balance in contract for attacker
        uint256 prevRecorded = c.Acc(atk).balance;

        // perform Put from attacker
        vm.prank(atk);
        // call Put with arbitrary unlock time (0 acceptable)
        (bool ok,) = address(c).call{value: sendAmount}(abi.encodeWithSignature("Put(uint256)", 0));
        // call should not revert on reference; mutant may behave differently but we only assert post-state

        // one universal assertion: the recorded Acc[attacker].balance is >= previous recorded plus ANY net amount that
        // attacker should have retained from its sends. For the safe contract, because Put is non-reentrant,
        // the final recorded balance must be at least prevRecorded + sendAmount - withdraws during Put. In the ref
        // there are no withdraws during Put, so we assert recorded balance >= prevRecorded + sendAmount.
        // This single assertion will hold for the reference for all inputs, and the mutant (without guard)
        // can break it by reentering and withdrawing during Put.

        uint256 finalRecorded = c.Acc(atk).balance;

        assertTrue(finalRecorded >= prevRecorded + sendAmount);
    }
}

// adversarial reentrant attacker: on receiving ether during Put (via fallback), it will optionally call Collect
// to withdraw funds from C, thereby reducing its recorded Acc.balance if C is vulnerable.
contract Attacker {
    C public target;
    bool public doReenter;
    uint256 public withdrawAmount;

    constructor(address _target) payable {
        target = C(_target);
    }

    function configure(bool _doReenter, uint256 _withdrawAmount) public {
        doReenter = _doReenter;
        withdrawAmount = _withdrawAmount;
    }

    // fallback will be invoked when C tries to call or send to this contract during Put
    fallback() external payable {
        if (doReenter) {
            // Attempt to withdraw from target; caller is this contract, which has been the depositor
            // We call Collect with withdrawAmount; if reentrancy is allowed, this may succeed and reduce Acc balance
            // Use low-level call to avoid reverts bubbling.
            (bool s,) = address(target).call(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));
            s;
        }
    }
}

