pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: attacker flag (whether to use malicious helper) and deposit amount
    function testFuzz_property(bool useAttacker, uint256 amt) public {
        // keep amount in a sensible range and non-zero to be meaningful
        amt = bound(amt, 0, 10 ether);

        address payer = address(0xBEEF);
        vm.deal(payer, 20 ether);

        bool ok;

        if (useAttacker) {
            // deploy a malicious helper that on fallback will revert, to model an external callee failure
            Reverter r = new Reverter();
            // we route calls by making msg.sender be the helper's address: the contract C uses msg.sender to index Acc
            // To do that we have the helper call into C from its fallback when it receives Ether. We'll make payer send Ether to the helper, which forwards into C via low-level call to trigger C.fallback -> Put(0) with msg.value
            // First fund helper so it can call into c
            vm.deal(address(r), amt);

            // Have the helper attempt to call into c; the helper will, in its fallback, call c with data that triggers c.fallback => Put(0)
            // We let payer send ETH to helper so helper's fallback executes and forwards into c
            vm.prank(payer);
            // The try/catch captures whether Put completed successfully (ok == true) or reverted (ok == false)
            try r.trigger{value: amt}(address(c)) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // direct normal call: payer calls Put via fallback (send to contract) to exercise the regular path
            vm.prank(payer);
            try address(c).call{value: amt}("") {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // The reference implementation's Put never reverts on these paths for any input, so assertTrue(ok) is a universal property it satisfies;
        // the mutant (removing nonReentrant_) can cause Put to fail for some inputs when an adversarial callee is involved.
        assertTrue(ok);
    }
}

// Adversarial helper that forwards a low-level call into the target C in a way that can trigger reentrancy or external failures.
contract Reverter {
    // When this contract receives Ether via trigger, it will call the target contract with empty data, making target's fallback run.
    // Additionally, its fallback will revert to simulate a failing external callee when appropriate.
    function trigger(address target) external payable {
        // forward Ether to target which invokes target.fallback -> Put(0)
        (bool s, ) = target.call{value: msg.value}("");
        if (!s) revert("forward failed");
    }

    // fallback reverts to model a callee that might cause low-level call failures if invoked differently
    fallback() external payable {
        revert("malicious fallback revert");
    }
}

